# -*- coding: utf-8 -*-
# (speaker, french, korean); speaker None => stage direction (not a turn)
H, J, JU, R = "Hélène", "Julien", "Julie", "Roux"
D = [
(None, "Samedi 19 décembre, 17 h 30. La salle est vide, les tables sont dressées. Julien range les menus. Hélène vérifie sa veste de cuisine dans le miroir du bar.", "12월 19일 토요일 오후 5시 30분. 홀은 비어 있고 테이블 세팅은 끝났다. 쥘리앵은 메뉴판을 정리하고, 엘렌은 바 거울 앞에서 조리복을 매만진다."),
(J, "Julie Marchetti arrive dans vingt minutes. Elle m'a dit qu'elle voulait voir la salle vide.", "쥘리 마르케티가 20분 뒤에 와. 빈 홀을 보고 싶다고 하더라."),
(H, "Qu'est-ce qu'elle t'a dit d'autre, au téléphone ? Répète-moi tout, dans l'ordre.", "전화로 또 뭐라고 했어? 순서대로 전부 다시 말해 줘."),
(J, "Elle a dit que l'entretien durerait trois quarts d'heure. Et qu'elle prendrait des photos.", "인터뷰는 45분쯤 걸릴 거고 사진도 찍을 거래."),
(H, "Des photos ? Personne ne m'a demandé si j'étais d'accord.", "사진? 내가 동의하는지 아무도 안 물어봤잖아."),
(J, "Elle m'a demandé si tu étais d'accord. J'ai répondu que tu y réfléchirais.", "네가 동의하는지 나한테 물었어. 생각해 보겠다고 대답해 놨지."),
(H, "Tu as bien fait. Et elle voulait savoir quoi, exactement ?", "잘했어. 그래서 정확히 뭘 알고 싶대?"),
(J, "Comment tu avais vécu la fermeture. Et pourquoi tu avais refusé de vendre.", "폐쇄 기간을 어떻게 겪었는지. 그리고 왜 가게를 안 팔았는지."),
(H, "Pourquoi j'avais refusé ? Elle est bien informée. Qui lui a dit ça ?", "내가 왜 거절했냐고? 정보가 빠르네. 누가 그런 얘기를 했대?"),
(J, "Elle ne l'a pas dit. Elle a juste précisé qu'elle dînerait ensuite, et qu'elle paierait sa note.", "말 안 했어. 인터뷰 후에 식사하고 계산도 자기가 하겠다고만 했지."),
(H, "Dîner ? Ce soir ? Elle va juger l'assiette et la patronne.", "식사? 오늘 밤에? 접시도 사장도 심사하겠다는 거네."),
(J, "Table neuf. Pas trop près de la cuisine, pas trop près de la porte.", "9번 테이블. 주방에서도 문에서도 너무 멀지 않게."),
(H, "Tu penses à tout. Moi, j'ai les mains moites.", "넌 다 신경 쓰는구나. 난 손에 땀이 나는데."),
(J, "Respire. Tu as survécu à une fermeture administrative, tu survivras à une journaliste.", "숨 쉬어. 행정 폐쇄도 이겨 냈는데 기자 한 명쯤이야."),
(None, "17 h 50. Julie Marchetti entre : la quarantaine, un manteau rouge, un petit enregistreur à la main.", "5시 50분. 쥘리 마르케티가 들어온다. 40대, 붉은 코트, 손에는 작은 녹음기."),
(J, "Madame Marchetti, bienvenue. Je vous laisse avec la patronne. Je suis au bar si besoin.", "마르케티 씨, 어서 오세요. 사장님께 맡기고 저는 바에 있을게요. 필요하시면 부르세요."),
(JU, "Merci, Julien. Madame Marchand, enchantée. Vous permettez que j'enregistre ? C'est pour ne rien déformer.", "고마워요, 쥘리앵. 마르샹 씨, 반갑습니다. 녹음해도 될까요? 내용을 왜곡하지 않으려는 거예요."),
(H, "Si vous voulez. Mais je préviens : je ne suis pas très bavarde.", "그러세요. 다만 미리 말해 두는데, 저는 말이 많은 편이 아니에요."),
(JU, "On m'avait prévenue. Votre père m'a même dit : « Elle va dire non à tout. Insistez. »", "들었어요. 아버님이 직접 이러셨거든요. \"얘는 뭐든 싫다고 할 거요. 끈질기게 물어보시오.\""),
(H, "Mon père vous a téléphoné ?", "아버지가 전화를 하셨다고요?"),
(JU, "Lundi matin. Il m'a dit que vous ne parleriez jamais de vous. Et qu'il fallait insister.", "월요일 아침에요. 당신은 절대 자기 얘기를 안 할 거라고, 그러니 끈질기게 물어야 한다고 하셨어요."),
(H, "Je vais lui parler, à celui-là. Allez-y, posez vos questions.", "그 양반하고는 따로 얘기해야겠네요. 시작하세요, 질문하세요."),
(JU, "D'abord : comment allez-vous, quatre jours après la réouverture ?", "먼저, 재개점 나흘째인데 기분이 어떠세요?"),
(H, "Fatiguée. Soulagée. Et un peu incrédule, pour être honnête.", "피곤해요. 안도했고요. 솔직히 말하면 좀 믿기지 않아요."),
(JU, "Incrédule ? Pourquoi ?", "믿기지 않는다고요? 왜요?"),
(H, "Parce que la salle est pleine. En septembre, je croyais que tout serait fini.", "홀이 가득 차 있으니까요. 9월엔 다 끝났다고 생각했거든요."),
(JU, "Vous avez dit « fini ». Vous avez donc pensé à tout arrêter ?", "\"끝났다\"고 하셨죠. 그럼 전부 그만둘 생각도 하신 거예요?"),
(H, "J'y ai pensé. Une nuit. Deux, peut-être. Pas plus. Vous pouvez l'écrire.", "생각했어요. 하룻밤. 어쩌면 이틀. 그 이상은 아니고요. 써도 돼요."),
(JU, "On m'a raconté qu'un groupe vous avait proposé cent quatre-vingt mille euros pour le fonds de commerce.", "어떤 그룹이 영업권 값으로 18만 유로를 제안했다는 얘기를 들었어요."),
(H, "Qui vous a raconté ça ?", "누가 그런 얘기를 했죠?"),
(JU, "Mes sources. Elles prétendent aussi que vous avez refusé en trois minutes.", "제 취재원들요. 3분 만에 거절하셨다고도 주장하더군요."),
(H, "Trois minutes, c'est faux. J'ai mis un mois à décider. Les chiffres, je ne les commente pas.", "3분이라는 건 거짓말이에요. 결정하는 데 한 달 걸렸어요. 숫자는 논평하지 않아요."),
(JU, "Je note : vous ne confirmez pas, vous ne démentez pas.", "적어 둘게요. 확인도 부인도 안 하시는 거죠."),
(H, "Écrivez ce que vous voulez. Mais écrivez que j'ai mis un mois.", "마음대로 쓰세요. 다만 한 달 걸렸다고는 써 주세요."),
(JU, "Entendu. Alors qu'est-ce qui vous a fait refuser, au bout d'un mois ?", "알겠어요. 그럼 한 달 끝에 거절하게 만든 건 뭐였나요?"),
(H, "Mon père m'a conseillé de vendre. Mon apprentie m'a demandé de ne pas le faire. J'ai écouté la plus têtue.", "아버지는 팔라고 조언하셨어요. 견습생은 팔지 말아 달라고 했고요. 더 고집 센 쪽 말을 들었죠."),
(JU, "Et votre père, comment a-t-il réagi quand vous avez dit non ?", "그럼 아버님은 거절하셨을 때 어떻게 반응하셨나요?"),
(H, "Il a crié. Puis il a dit qu'il était fier. Dans cet ordre. Ça, c'est off.", "소리를 지르셨죠. 그러고는 자랑스럽다고 하셨어요. 이 순서대로요. 이건 오프예요."),
(JU, "Off, d'accord. Je ne l'utiliserai pas. Mais je peux écrire que tout s'est réglé ?", "오프 알겠어요. 쓰지 않을게요. 하지만 모든 게 풀렸다고는 써도 되나요?"),
(H, "Écrivez que c'est réglé. C'est tout ce qui compte.", "풀렸다고 쓰세요. 그게 가장 중요하니까요."),
(JU, "Votre père m'a aussi parlé d'un carnet de recettes. Celui de votre mère.", "아버님이 레시피 노트 얘기도 하셨어요. 어머님 거요."),
(H, "Il vous a parlé de ça aussi ? Décidément.", "그 얘기까지요? 정말이지."),
(JU, "Je peux écrire qu'il existe ? Pas ce qu'il y a dedans.", "그 노트가 있다고 써도 될까요? 내용은 말고요."),
(H, "Qu'il existe, oui. Que nous l'avons retrouvé, oui. Le reste, c'est à nous.", "있다는 건 돼요. 다시 찾았다는 것도요. 나머지는 우리 거예요."),
(JU, "Parfait. Passons à la cuisine. Comment la définiriez-vous, en une phrase ?", "좋아요. 요리 얘기로 넘어갈게요. 한 문장으로 정의하신다면요?"),
(H, "Une cuisine qui ne triche pas. Du beurre, du temps, des produits qu'on connaît.", "속임수 없는 요리요. 버터, 시간, 출처를 아는 재료."),
(JU, "Et en face ? Il paraît que vous et Victor Lambert ne vous parlez plus.", "그리고 맞은편은요? 빅토르 랑베르 씨와 서로 말을 안 한다던데요."),
(H, "Il paraît beaucoup de choses. Il est venu jeudi. On s'est parlé. Point final.", "소문이야 많죠. 목요일에 그가 왔어요. 우린 얘기했고요. 그게 끝이에요."),
(JU, "Il est venu pour quoi faire ?", "무슨 일로 왔는데요?"),
(H, "Pour me dire qu'une rue avec deux restaurants vivants vaut mieux qu'une rue avec un seul.", "활기 있는 식당 둘이 있는 거리가 하나만 있는 거리보다 낫다고 말하러요."),
(JU, "Joli. Je peux le citer, entre guillemets ?", "멋진데요. 따옴표 안에 인용해도 될까요?"),
(H, "Vous pouvez. Mais précisez que c'est sa phrase, pas la mienne.", "돼요. 하지만 제 문장이 아니라 그 사람 문장이라고 밝혀 주세요."),
(JU, "Je le préciserai. Dernière question : que voudriez-vous que les lecteurs retiennent ?", "그렇게 할게요. 마지막 질문입니다. 독자들이 무엇을 기억하길 바라세요?"),
(H, "Que ce n'est pas un miracle. C'est mille deux cent trente-sept personnes, de l'entêtement et beaucoup de beurre.", "기적이 아니라는 거요. 1,237명, 고집, 그리고 엄청난 양의 버터요."),
(JU, "Je peux résumer pour vérifier ? Vous m'avez dit que vous aviez pensé à tout arrêter.", "확인차 요약해도 될까요? 모든 걸 그만둘 생각을 했다고 말씀하셨어요."),
(JU, "Que vous aviez refusé une offre de cent quatre-vingt mille euros, et que votre père avait pleuré.", "18만 유로 제안을 거절했고, 아버님이 우셨다고도요."),
(H, "Stop. Je n'ai pas dit ça. J'ai dit que je ne commentais pas les chiffres. Et il n'a pas pleuré.", "잠깐요. 그렇게 말하지 않았어요. 숫자는 논평하지 않는다고 했죠. 그리고 아버지는 안 우셨어요."),
(JU, "Vous avez raison. Je corrige : « Elle n'a pas souhaité commenter. » Et le père ne pleure pas.", "맞아요. 정정할게요. \"그녀는 논평을 원하지 않았다.\" 그리고 아버지는 울지 않았다."),
(H, "Je veux relire mes citations avant la publication. C'est possible ?", "발행 전에 제 인용문을 다시 읽고 싶어요. 가능한가요?"),
(JU, "C'est l'usage. Je vous les envoie lundi. Vous pouvez changer la forme, pas le fond.", "관례예요. 월요일에 보내 드릴게요. 표현은 바꿔도 되지만 내용은 안 돼요."),
(H, "Le fond, c'est justement ce qui m'inquiète.", "내용이야말로 제가 걱정하는 거예요."),
(JU, "Je vous promets un portrait honnête. Une photo devant l'ardoise, et je vous laisse travailler ?", "솔직한 인물 기사를 약속드려요. 칠판 앞에서 사진 한 장 찍고 일하시게 해 드릴까요?"),
(H, "Une photo. Une seule. Et sans sourire forcé.", "사진 한 장. 딱 한 장. 억지웃음은 없이요."),
(JU, "Votre père m'a dit que vous souriiez deux fois par an. On va essayer d'en profiter.", "아버님이 당신은 1년에 두 번 웃는다고 하셨어요. 그 기회를 한번 노려 볼게요."),
(None, "19 h 50. La salle est pleine. À la table neuf, Julie Marchetti lit le menu. Julien rejoint Hélène au passe-plat.", "7시 50분. 홀이 가득 찼다. 9번 테이블에서 쥘리 마르케티가 메뉴를 읽는다. 쥘리앵이 주방 창구에서 엘렌과 만난다."),
(J, "Table neuf : soupe à l'oignon, puis blanquette. Elle m'a demandé si la sauce était faite à la minute.", "9번: 양파 수프, 그다음 블랑케트. 소스를 주문 즉시 만드는지 물었어."),
(H, "Et tu as répondu quoi ?", "그래서 뭐라고 대답했어?"),
(J, "Que la sauce était faite le matin, selon la recette de Marthe. Elle a noté.", "소스는 아침에 마르트의 레시피대로 만든다고. 받아 적더라."),
(H, "Elle note tout, celle-là. Karim, table neuf à vingt heures trente, ni avant ni après.", "저 사람은 다 받아 적네. 카림, 9번은 8시 30분 정각, 그 전도 후도 안 돼."),
(J, "Karim m'a répondu qu'il ne changerait rien. Qu'il ferait comme d'habitude, avec un peu plus de beurre.", "카림이 아무것도 안 바꾸겠대. 평소처럼 하되 버터만 조금 더 넣겠다고."),
(H, "Pas plus de beurre ! Les critiques voient tout de suite quand on change quelque chose.", "버터를 더 넣지 마! 비평가들은 뭔가 바뀌면 바로 알아본다고."),
(J, "Hélène... il y en a un deuxième.", "엘렌... 한 명 더 있어."),
(H, "Un deuxième quoi ?", "한 명 더 뭐가?"),
(J, "Un deuxième critique. Table quatre, seul, la soixantaine, canne noire. Réservé au nom d'« Étienne ».", "비평가가 한 명 더 왔어. 4번 테이블, 혼자, 예순 정도, 검은 지팡이. \"에티엔\"이라는 이름으로 예약했고."),
(H, "Étienne Roux. Le vrai. Celui d'octobre.", "에티엔 루. 진짜 그 사람. 10월의 그 사람이구나."),
(J, "Il a refusé que je prenne son manteau. Il a demandé qui avait choisi les vins.", "코트 받아 주는 것도 거절했어. 와인은 누가 골랐냐고 묻더라."),
(H, "Deux critiques le même soir. Hasard ou mauvaise blague ?", "같은 날 저녁에 비평가 둘. 우연이야, 나쁜 농담이야?"),
(J, "Ni l'un ni l'autre. Elle écrit pour dimanche. Lui, c'est son flair.", "둘 다 아니지. 그 사람은 일요일자 기사를 쓰고, 저 사람은 그냥 촉이지."),
(H, "On ne change rien. Tu les sers comme tout le monde. Ni plus vite, ni plus lentement.", "아무것도 안 바꿔. 다른 손님과 똑같이 서빙해. 더 빠르게도 더 느리게도 말고."),
(J, "Compris. Mais je te préviens : ils se sont reconnus.", "알았어. 하지만 미리 말해 두는데, 둘이 서로 알아봤어."),
(None, "Au milieu de la salle, Julie se lève, traverse entre les tables et s'arrête devant la table quatre.", "홀 한가운데서 쥘리가 일어나 테이블 사이를 지나 4번 테이블 앞에 멈춰 선다."),
(JU, "Étienne Roux. On m'avait dit que vous ne sortiez que le mardi.", "에티엔 루. 화요일에만 외출하신다고 들었는데요."),
(R, "Julie Marchetti. Et moi, on m'avait dit que vous ne jugiez plus les restaurants.", "쥘리 마르케티. 저는 당신이 더 이상 식당을 평가하지 않는다고 들었는데."),
(JU, "Je ne les juge plus. Je les écoute. Vous devriez essayer.", "더는 평가하지 않아요. 귀를 기울이죠. 당신도 해 보세요."),
(R, "Écouter ne se mange pas, chère amie. Retournez à votre table, votre soupe refroidit.", "듣는 건 먹을 수가 없소, 친애하는 이여. 자리로 돌아가시오, 수프 식겠소."),
(JU, "Elle n'est pas encore servie. Bonne soirée, Étienne. Ne soyez pas trop méchant.", "아직 안 나왔어요. 즐거운 저녁 보내요, 에티엔. 너무 심술궂게 굴진 마시고."),
(R, "Je ne suis jamais méchant. Je suis exact. Nuance.", "나는 절대 심술궂지 않소. 정확할 뿐이지. 차이가 있소."),
(J, "Monsieur, souhaitez-vous que je vous présente la carte ? Nous avons dix plats en ce moment.", "손님, 메뉴를 설명해 드릴까요? 지금 요리는 열 가지예요."),
(R, "Je l'ai lue dans la rue, sur l'ardoise. Que me conseillez-vous ?", "길에서 칠판으로 읽었소. 뭘 추천하겠소?"),
(J, "La cheffe m'a demandé de ne rien vous conseiller, monsieur.", "주방장님이 손님께는 아무것도 추천하지 말라고 하셨습니다."),
(R, "Donc elle m'a reconnu. Tant mieux : j'aime les gens qui s'y attendent.", "그럼 알아봤다는 거군. 잘됐소. 각오하고 있는 사람이 좋소."),
(J, "Elle m'a aussi dit de vous préciser qu'on vous servirait comme n'importe quel client.", "또 손님께 다른 손님과 똑같이 모시겠다고 전하라고 하셨습니다."),
(R, "Alors je prendrai la poule au pot, puis la tarte Tatin. Sans attendre le dessert pour me décider.", "그럼 풀레 오 포 하고 타르트 타탱으로 하겠소. 디저트 때까지 고민하지 않고."),
(J, "Très bien. Avec un verre de vin ? Un brouilly, peut-être ?", "알겠습니다. 와인 한 잔 곁들이시겠어요? 브루이 어떠세요?"),
(R, "Brouilly, oui. Le moins cher que vous ayez. Je juge mieux avec un vin simple.", "브루이 좋소. 있는 것 중 가장 싼 걸로. 소박한 와인일 때 더 잘 판단하거든."),
(J, "Bien, monsieur. Je vous l'apporte tout de suite.", "알겠습니다, 손님. 바로 가져다드리겠습니다."),
(None, "21 h 30. Le service se calme. Hélène sort de sa cuisine en s'essuyant les mains.", "9시 30분. 영업이 잠잠해진다. 엘렌이 손을 닦으며 주방에서 나온다."),
(H, "La neuf a tout mangé. Elle n'a presque rien dit, elle a seulement écrit dans son carnet.", "9번 손님이 전부 먹었어. 거의 말도 없이 수첩에 뭘 적기만 했고."),
(J, "Elle m'a demandé de te féliciter pour la sauce. Mais « sans que ça compte dans l'article ».", "소스가 좋았다고 전해 달래. 그런데 \"기사에는 반영 안 되는 걸로\" 하자면서."),
(H, "Ça ne veut rien dire, ça. Et l'autre ?", "그건 아무 의미도 없잖아. 다른 쪽은?"),
(J, "Roux ? La poule au pot, il a tout vidé, même le bouillon. Il a demandé si le bouillon datait de la veille.", "루? 풀레 오 포를 국물까지 다 비웠어. 국물이 전날 끓인 거냐고 묻더라."),
(H, "Tu lui as dit quoi ?", "뭐라고 했어?"),
(J, "Que oui, qu'il était passé et dégraissé. Il a hoché la tête.", "그렇다고, 걸러서 기름기도 걷어 냈다고. 고개를 끄덕였어."),
(H, "Hocher la tête, c'est bon signe ou mauvais signe ?", "고개를 끄덕이는 건 좋은 신호야, 나쁜 신호야?"),
(J, "Avec lui, ça veut dire qu'il a hoché la tête. Pas plus.", "그 사람한테는 고개를 끄덕였다는 뜻일 뿐이야. 그 이상은 아니고."),
(None, "22 h 10. Roux a fini sa tarte. Il fait un signe à Julien et demande à voir la cheffe.", "10시 10분. 루는 타르트를 다 먹고 쥘리앵에게 손짓하며 주방장을 만나고 싶다고 한다."),
(J, "Hélène, Roux demande si tu as une minute. Il a précisé que ce n'était pas une plainte.", "엘렌, 루가 잠깐 시간 있느냐고 해. 불만 때문은 아니라고 밝혔어."),
(H, "Il t'a vraiment dit ça ? Bon. J'y vais.", "정말 그렇게 말했어? 좋아. 갈게."),
(R, "Madame Marchand. Rassurez-vous : je ne vous dirai rien ce soir. Je n'écris jamais à chaud.", "마르샹 부인. 안심하시오. 오늘 밤은 아무 말도 하지 않겠소. 나는 열기가 식기 전에는 쓰지 않으니."),
(H, "Merci d'être venu, monsieur Roux. Même si je ne sais pas si je dois vous remercier.", "와 주셔서 감사합니다, 루 선생님. 감사해야 하는 건지는 모르겠지만요."),
(R, "Vous avez raison de vous méfier. En octobre, j'ai été dur avec vous.", "경계하는 게 맞소. 10월에 내가 당신에게 가혹했으니."),
(H, "Je m'en souviens mot pour mot.", "한 마디도 빠짐없이 기억해요."),
(R, "Je ne retire rien. Mais ce soir, quelqu'un a cuisiné pour moi, pas contre moi.", "철회하는 건 없소. 하지만 오늘 밤은 누군가 나를 겨냥해서가 아니라 나를 위해 요리해 주었소."),
(H, "Pardon ? Qui vous a dit cette phrase ?", "네? 그 문장은 누가 알려 줬나요?"),
(R, "Quelle phrase ? Je viens de l'inventer, madame. Vous êtes toute pâle.", "무슨 문장 말이오? 방금 내가 지어낸 거요, 부인. 얼굴이 하얘졌구려."),
(H, "Rien. Une coïncidence. Bonne nuit, monsieur Roux.", "아니에요. 우연이에요. 안녕히 가세요, 루 선생님."),
(R, "Bonne nuit. Dites à votre jeune homme que le brouilly était honnête.", "잘 가시오. 저 젊은 친구에게 브루이가 정직했다고 전해 주시오."),
(None, "23 h 05. Les deux critiques sont partis. Julien ferme la caisse. Hélène s'assied enfin au bar.", "11시 5분. 두 비평가는 떠났다. 쥘리앵이 계산대를 닫는다. 엘렌이 마침내 바에 앉는다."),
(J, "Julie m'a dit de te dire qu'elle t'enverrait le texte lundi, avant le bouclage.", "쥘리가 마감 전인 월요일에 원고를 보내겠다고 전해 달래."),
(H, "Et lui ?", "그리고 그 사람은?"),
(J, "Il m'a dit qu'il reviendrait « quand on ne l'attendrait plus ».", "\"아무도 기다리지 않을 때\" 다시 오겠대."),
(H, "Alors on l'attendra tous les soirs. Comme ça, il ne nous surprendra jamais.", "그럼 매일 저녁 기다리면 되겠네. 그러면 절대 놀라진 않을 테니."),
(J, "Tu l'as trouvée comment, la journaliste ?", "그 기자는 어땠어?"),
(H, "Honnête. Têtue. Elle écrit ce qu'elle a vu, ça se sent.", "정직하고 고집이 세. 본 대로 쓰는 사람이야, 느껴져."),
(J, "Et si l'article est mauvais ?", "그럼 기사가 나쁘게 나오면?"),
(H, "On aura quand même cuisiné comme on cuisine. Ferme la caisse, je vais voir Karim.", "그래도 우리 방식대로 요리한 거야. 계산대 닫아, 난 카림 보러 갈게."),
(J, "Hélène ? Tu as souri deux fois ce soir. Je les ai comptées.", "엘렌? 오늘 밤 두 번 웃었어. 내가 세어 봤어."),
]

